CREATE OR REPLACE FUNCTION public.remember_guest_link_vault_read(p_actor uuid, p_album uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v text;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM remember.webmasters w JOIN remember.albums a ON a.owner_user_id=w.user_id WHERE w.user_id=p_actor AND a.id=p_album) THEN RETURN NULL; END IF;
 SELECT ciphertext INTO v FROM remember.guest_link_vault WHERE album_id=p_album;
 RETURN v;
END $function$

CREATE OR REPLACE FUNCTION public.remember_guest_metadata_read(p_token_hash bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_title text;
 v_opens timestamptz;
 v_closes timestamptz;
 v_closed boolean;
BEGIN
 IF p_token_hash IS NULL OR octet_length(p_token_hash) <> 32
 THEN RETURN jsonb_build_object('found', false); END IF;

 SELECT a.title,
        COALESCE(a.override_opens_at, a.default_opens_at),
        COALESCE(a.override_closes_at, a.default_closes_at),
        a.forced_closed
 INTO v_title, v_opens, v_closes, v_closed
 FROM remember.guest_links g
 JOIN remember.albums a ON a.id = g.album_id
 WHERE g.token_sha256 = p_token_hash AND g.revoked_at IS NULL;

 IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;

 RETURN jsonb_build_object(
  'found', true,
  'title', v_title,
  'uploadsOpen', NOT COALESCE(v_closed, true)
     AND now() >= v_opens AND now() < v_closes
 );
END $function$

CREATE OR REPLACE FUNCTION public.remember_guest_photo_reserve(p_token_hash bytea, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_album remember.albums%ROWTYPE;
 v_existing remember.album_photos%ROWTYPE;
 v_used integer;
 v_photo_id uuid;
 v_key text;
BEGIN
 IF p_token_hash IS NULL OR octet_length(p_token_hash)<>32 OR p_request_id IS NULL THEN
  RETURN jsonb_build_object('accepted',false,'reason','invalid');
 END IF;
 SELECT a.* INTO v_album FROM remember.guest_links g JOIN remember.albums a ON a.id=g.album_id
 WHERE g.token_sha256=p_token_hash AND g.revoked_at IS NULL FOR UPDATE OF a;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'reason','invalid'); END IF;
 SELECT * INTO v_existing FROM remember.album_photos WHERE album_id=v_album.id AND idempotency_key=p_request_id;
 IF FOUND THEN
  IF v_existing.state='reserved' AND v_existing.reservation_expires_at<=now() THEN
   UPDATE remember.album_photos SET state='failed' WHERE id=v_existing.id;
  END IF;
  RETURN jsonb_build_object('accepted',v_existing.state='ready' OR (v_existing.state IN ('reserved','uploading') AND v_existing.reservation_expires_at>now()),'reason','existing','photoId',v_existing.id);
 END IF;
 IF v_album.forced_closed OR now()<COALESCE(v_album.override_opens_at,v_album.default_opens_at)
 OR now()>=COALESCE(v_album.override_closes_at,v_album.default_closes_at)
 THEN RETURN jsonb_build_object('accepted',false,'reason','closed'); END IF;
 UPDATE remember.album_photos SET state='failed' WHERE album_id=v_album.id AND state='reserved' AND reservation_expires_at<=now();
 SELECT count(*) INTO v_used FROM remember.album_photos p
 WHERE p.album_id=v_album.id AND p.state IN ('reserved','uploading','ready')
 AND NOT EXISTS(SELECT 1 FROM remember.photo_approval_queue q WHERE q.photo_id=p.id AND q.decision='rejected');
 IF v_used>=v_album.photo_limit THEN RETURN jsonb_build_object('accepted',false,'reason','limit'); END IF;
 v_photo_id:=gen_random_uuid();v_key:=v_album.id::text||'/'||v_photo_id::text;
 INSERT INTO remember.album_photos(id,album_id,object_key,idempotency_key,state,reservation_expires_at)
 VALUES(v_photo_id,v_album.id,v_key,p_request_id,'reserved',now()+interval '15 minutes');
 RETURN jsonb_build_object('accepted',true,'reason','reserved','photoId',v_photo_id);
END $function$

CREATE OR REPLACE FUNCTION public.remember_photo_approval_owner_decide(p_actor uuid, p_album uuid, p_photo uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF p_actor IS NULL OR NOT EXISTS(SELECT 1 FROM remember.albums WHERE id=p_album AND owner_user_id=p_actor)
 THEN RAISE EXCEPTION 'album_owner_required' USING ERRCODE='42501'; END IF;
 IF p_decision NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'invalid_decision' USING ERRCODE='22023'; END IF;
 IF NOT public.remember_security_effective_feature_read(p_album,'photo_approval')
 THEN RAISE EXCEPTION 'feature_disabled' USING ERRCODE='22023'; END IF;
 PERFORM 1 FROM remember.photo_approval_queue q JOIN remember.album_photos p ON p.id=q.photo_id
 WHERE q.photo_id=p_photo AND q.album_id=p_album AND p.album_id=p_album AND p.state='ready' FOR UPDATE OF q;
 IF NOT FOUND THEN RAISE EXCEPTION 'photo_not_in_queue' USING ERRCODE='22023'; END IF;
 UPDATE remember.photo_approval_queue SET decision=p_decision,decided_by=p_actor,decided_at=now()
 WHERE photo_id=p_photo AND album_id=p_album AND decision='pending';
 IF NOT FOUND THEN RAISE EXCEPTION 'already_decided' USING ERRCODE='22023'; END IF;
 RETURN jsonb_build_object('ok',true,'photoId',p_photo,'decision',p_decision);
END $function$

CREATE OR REPLACE FUNCTION public.remember_photo_approval_owner_queue_read(p_actor uuid, p_album uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_result jsonb; v_active boolean;
BEGIN
 IF p_actor IS NULL OR p_album IS NULL OR NOT EXISTS(SELECT 1 FROM remember.albums WHERE id=p_album AND owner_user_id=p_actor)
 THEN RAISE EXCEPTION 'album_owner_required' USING ERRCODE='42501'; END IF;
 v_active:=public.remember_security_effective_feature_read(p_album,'photo_approval');
 SELECT coalesce(jsonb_agg(jsonb_build_object('photo_id',q.photo_id,'decision',q.decision,'created_at',q.created_at,'decided_at',q.decided_at,'expires_at',CASE WHEN q.decision='rejected' THEN q.decided_at+interval '72 hours' ELSE NULL END,'object_key',p.object_key) ORDER BY q.created_at DESC),'[]'::jsonb)
 INTO v_result FROM remember.photo_approval_queue q JOIN remember.album_photos p ON p.id=q.photo_id
 WHERE q.album_id=p_album AND p.album_id=p_album AND p.state='ready';
 RETURN jsonb_build_object('photos',v_result,'readOnly',NOT v_active,'featureEnabled',v_active);
END $function$

CREATE OR REPLACE FUNCTION public.remember_photo_begin_upload(p_photo_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_photo remember.album_photos%ROWTYPE;
BEGIN
 IF p_photo_id IS NULL THEN RETURN jsonb_build_object('accepted',false); END IF;
 SELECT * INTO v_photo FROM remember.album_photos WHERE id=p_photo_id FOR UPDATE;
 IF NOT FOUND OR v_photo.state<>'reserved' OR v_photo.reservation_expires_at<=now()
 THEN RETURN jsonb_build_object('accepted',false); END IF;
 UPDATE remember.album_photos SET state='uploading' WHERE id=p_photo_id;
 RETURN jsonb_build_object('accepted',true,'objectKey',v_photo.object_key);
END $function$

CREATE OR REPLACE FUNCTION public.remember_photo_claim_upload(p_photo_id uuid, p_content_sha256 bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_photo remember.album_photos%ROWTYPE;
BEGIN
 IF p_photo_id IS NULL OR p_content_sha256 IS NULL OR octet_length(p_content_sha256)<>32
 THEN RETURN jsonb_build_object('accepted',false,'reason','invalid'); END IF;
 SELECT * INTO v_photo FROM remember.album_photos WHERE id=p_photo_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'reason','not_found'); END IF;
 IF v_photo.state='uploading' AND v_photo.content_sha256=p_content_sha256
 THEN RETURN jsonb_build_object('accepted',false,'reason','in_progress','photoId',v_photo.id); END IF;
 IF v_photo.state='ready' AND v_photo.content_sha256=p_content_sha256
 THEN RETURN jsonb_build_object('accepted',false,'reason','already_ready','photoId',v_photo.id); END IF;
 IF v_photo.state<>'reserved' OR v_photo.reservation_expires_at<=now()
 THEN RETURN jsonb_build_object('accepted',false,'reason','invalid_state'); END IF;
 BEGIN
  UPDATE remember.album_photos
  SET state='uploading',content_sha256=p_content_sha256
  WHERE id=v_photo.id;
 EXCEPTION WHEN unique_violation THEN
  -- The unique-index conflict rolled back the claim subtransaction.
  -- This reservation never reached storage: release its unused quota slot.
  UPDATE remember.album_photos SET state='failed'
  WHERE id=v_photo.id AND state='reserved';
  RETURN jsonb_build_object('accepted',false,'reason','duplicate');
 END;
 RETURN jsonb_build_object('accepted',true,'reason','claimed',
   'photoId',v_photo.id,'objectKey',v_photo.object_key);
END $function$

CREATE OR REPLACE FUNCTION public.remember_photo_complete_upload(p_photo_id uuid, p_token_hash bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_photo remember.album_photos%ROWTYPE; v_approval boolean;
BEGIN
 IF p_photo_id IS NULL OR p_token_hash IS NULL OR octet_length(p_token_hash)<>32 THEN RETURN jsonb_build_object('accepted',false); END IF;
 SELECT * INTO v_photo FROM remember.album_photos WHERE id=p_photo_id FOR UPDATE;
 IF NOT FOUND OR v_photo.state<>'uploading' THEN RETURN jsonb_build_object('accepted',false); END IF;
 IF NOT EXISTS(SELECT 1 FROM remember.guest_links g WHERE g.album_id=v_photo.album_id AND g.token_sha256=p_token_hash AND g.revoked_at IS NULL)
 OR NOT EXISTS(SELECT 1 FROM remember.albums a WHERE a.id=v_photo.album_id AND NOT a.forced_closed AND now()>=coalesce(a.override_opens_at,a.default_opens_at) AND now()<coalesce(a.override_closes_at,a.default_closes_at))
 THEN RETURN jsonb_build_object('accepted',false); END IF;
 v_approval:=public.remember_security_effective_feature_read(v_photo.album_id,'photo_approval');
 IF v_approval THEN INSERT INTO remember.photo_approval_queue(photo_id,album_id) VALUES(p_photo_id,v_photo.album_id) ON CONFLICT(photo_id) DO NOTHING; END IF;
 UPDATE remember.album_photos SET state='ready' WHERE id=p_photo_id;
 RETURN jsonb_build_object('accepted',true,'awaitingApproval',v_approval);
END $function$

CREATE OR REPLACE FUNCTION public.remember_photo_fail_upload(p_photo_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_photo remember.album_photos%ROWTYPE;
BEGIN
 IF p_photo_id IS NULL THEN RETURN jsonb_build_object('accepted',false); END IF;
 SELECT * INTO v_photo FROM remember.album_photos WHERE id=p_photo_id FOR UPDATE;
 IF NOT FOUND OR v_photo.state NOT IN ('reserved','uploading')
 THEN RETURN jsonb_build_object('accepted',false); END IF;
 UPDATE remember.album_photos SET state='failed' WHERE id=p_photo_id;
 RETURN jsonb_build_object('accepted',true);
END $function$

CREATE OR REPLACE FUNCTION public.remember_photo_gallery_read(p_actor uuid, p_album_id uuid, p_token_hash bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE aid uuid; items jsonb; v_guest boolean:=false; v_approval boolean:=false;
BEGIN
 IF p_actor IS NOT NULL AND p_album_id IS NOT NULL AND p_token_hash IS NULL THEN
  IF NOT EXISTS(SELECT 1 FROM remember.webmasters WHERE user_id=p_actor) THEN RETURN jsonb_build_object('authorized',false); END IF;
  aid:=p_album_id;
 ELSIF p_actor IS NULL AND p_album_id IS NULL AND p_token_hash IS NOT NULL AND octet_length(p_token_hash)=32 THEN
  v_guest:=true;
  SELECT album_id INTO aid FROM remember.guest_links WHERE token_sha256=p_token_hash AND revoked_at IS NULL;
 ELSE RETURN jsonb_build_object('authorized',false); END IF;
 IF aid IS NULL OR NOT EXISTS(SELECT 1 FROM remember.albums WHERE id=aid) THEN RETURN jsonb_build_object('authorized',false); END IF;
 IF v_guest THEN v_approval:=public.remember_security_effective_feature_read(aid,'photo_approval'); END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'objectKey',p.object_key,'createdAt',p.created_at) ORDER BY p.created_at DESC,p.id DESC),'[]'::jsonb)
 INTO items FROM (
  SELECT photo.id,photo.object_key,photo.created_at FROM remember.album_photos photo
  WHERE photo.album_id=aid AND photo.state='ready'
   AND (NOT v_guest OR NOT EXISTS(SELECT 1 FROM remember.photo_approval_queue q WHERE q.photo_id=photo.id AND q.decision='rejected'))
   AND (NOT v_approval OR NOT EXISTS(SELECT 1 FROM remember.photo_approval_queue q WHERE q.photo_id=photo.id)
    OR EXISTS(SELECT 1 FROM remember.photo_approval_queue q WHERE q.photo_id=photo.id AND q.album_id=aid AND q.decision='approved'))
  ORDER BY photo.created_at DESC,photo.id DESC LIMIT 100
 ) p;
 RETURN jsonb_build_object('authorized',true,'photos',items);
END $function$

CREATE OR REPLACE FUNCTION public.remember_photo_quarantine_finalize(p_photo uuid, p_album uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_key text;
BEGIN
 SELECT p.object_key INTO v_key FROM remember.photo_quarantine_purge_claims c
 JOIN remember.photo_approval_queue q ON q.photo_id=c.photo_id
 JOIN remember.album_photos p ON p.id=q.photo_id AND p.album_id=q.album_id
 WHERE c.photo_id=p_photo AND q.album_id=p_album AND q.decision='rejected'
 AND q.decided_at <= now()-interval '72 hours' AND p.state='ready'
 FOR UPDATE OF q;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false); END IF;
 DELETE FROM remember.album_photos WHERE id=p_photo AND album_id=p_album AND object_key=v_key;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false); END IF;
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.remember_photo_quarantine_finalize(p_photo uuid, p_album uuid, p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_key text;
begin
 select p.object_key into v_key
 from remember.photo_quarantine_purge_claims c
 join remember.photo_approval_queue q on q.photo_id=c.photo_id
 join remember.album_photos p on p.id=q.photo_id and p.album_id=q.album_id
 where c.photo_id=p_photo and c.claim_token=p_token and q.album_id=p_album
 and q.decision='rejected' and q.decided_at<=now()-interval '72 hours' and p.state='ready'
 for update of q;
 if not found then return jsonb_build_object('ok',false); end if;
 delete from remember.album_photos where id=p_photo and album_id=p_album and object_key=v_key;
 if not found then return jsonb_build_object('ok',false); end if;
 return jsonb_build_object('ok',true);
end $function$

CREATE OR REPLACE FUNCTION public.remember_photo_quarantine_restore(p_actor uuid, p_album uuid, p_photo uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_limit integer;v_used integer;v_decided timestamptz;
BEGIN
 IF p_actor IS NULL OR p_album IS NULL OR p_photo IS NULL THEN RAISE EXCEPTION 'invalid_request' USING ERRCODE='22023'; END IF;
 SELECT photo_limit INTO v_limit FROM remember.albums WHERE id=p_album AND owner_user_id=p_actor FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'album_owner_required' USING ERRCODE='42501'; END IF;
 IF NOT public.remember_security_effective_feature_read(p_album,'photo_approval') THEN RAISE EXCEPTION 'feature_disabled' USING ERRCODE='22023'; END IF;
 SELECT q.decided_at INTO v_decided FROM remember.photo_approval_queue q JOIN remember.album_photos p ON p.id=q.photo_id
 WHERE q.photo_id=p_photo AND q.album_id=p_album AND p.album_id=p_album AND p.state='ready' AND q.decision='rejected' FOR UPDATE OF q;
 IF NOT FOUND THEN RAISE EXCEPTION 'not_quarantined' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM remember.photo_quarantine_purge_claims WHERE photo_id=p_photo) THEN RAISE EXCEPTION 'purge_in_progress' USING ERRCODE='22023'; END IF;
 IF v_decided IS NULL OR v_decided+interval '72 hours'<=now() THEN RAISE EXCEPTION 'quarantine_expired' USING ERRCODE='22023'; END IF;
 SELECT count(*) INTO v_used FROM remember.album_photos p WHERE p.album_id=p_album AND p.state IN ('reserved','uploading','ready')
 AND NOT EXISTS(SELECT 1 FROM remember.photo_approval_queue q WHERE q.photo_id=p.id AND q.decision='rejected');
 IF v_used>=v_limit THEN RAISE EXCEPTION 'album_limit_reached' USING ERRCODE='22023'; END IF;
 UPDATE remember.photo_approval_queue SET decision='approved',decided_at=now(),decided_by=p_actor WHERE photo_id=p_photo AND album_id=p_album AND decision='rejected';
 RETURN jsonb_build_object('ok',true,'photoId',p_photo,'decision','approved');
END $function$

CREATE OR REPLACE FUNCTION public.remember_security_effective_feature_read(p_album uuid, p_feature text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'remember'
AS $function$
DECLARE v_mode text; v_enabled boolean;
BEGIN
 IF p_album IS NULL OR p_feature IS NULL OR p_feature NOT IN ('verified_guest_email','photo_approval','guest_reports','report_notifications','slideshow_pause','quota_notifications') THEN RETURN false; END IF;
 SELECT f.mode INTO v_mode FROM remember.security_feature_flags f WHERE f.feature_key=p_feature;
 IF v_mode IS DISTINCT FROM 'TEST' THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM remember.security_test_eligibility e WHERE e.feature_key=p_feature AND e.album_id=p_album) THEN RETURN false; END IF;
 IF p_feature='quota_notifications' THEN RETURN true; END IF;
 SELECT CASE p_feature
 WHEN 'verified_guest_email' THEN s.require_verified_email
 WHEN 'photo_approval' THEN s.require_photo_approval
 WHEN 'guest_reports' THEN s.allow_reports
 WHEN 'report_notifications' THEN s.notify_reports
 WHEN 'slideshow_pause' THEN s.pause_new_slideshow_photos
 ELSE false END INTO v_enabled
 FROM remember.security_album_settings s WHERE s.album_id=p_album;
 RETURN COALESCE(v_enabled,false);
END $function$

CREATE OR REPLACE FUNCTION public.remember_security_owner_setting_write(p_actor uuid, p_request_id uuid, p_album uuid, p_setting text, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_payload jsonb;
 v_existing remember.security_request_ledger%ROWTYPE;
 v_before boolean;
 v_result jsonb;
BEGIN
 IF p_actor IS NULL OR p_request_id IS NULL OR p_album IS NULL OR p_setting IS NULL OR p_enabled IS NULL
 THEN RAISE EXCEPTION 'Missing argument' USING ERRCODE='22023'; END IF;
 IF p_setting NOT IN ('require_verified_email','require_photo_approval',
   'allow_reports','notify_reports','pause_new_slideshow_photos')
 THEN RAISE EXCEPTION 'Invalid setting' USING ERRCODE='22023'; END IF;
 v_payload := jsonb_build_array(p_actor,p_album,p_setting,p_enabled);
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request_id::text,0));
 SELECT * INTO v_existing FROM remember.security_request_ledger WHERE request_id=p_request_id;
 IF FOUND THEN
  IF v_existing.actor_user_id<>p_actor OR v_existing.request_payload<>v_payload
  THEN RAISE EXCEPTION 'Request conflict' USING ERRCODE='23505'; END IF;
  RETURN v_existing.result;
 END IF;
 -- The actor must have been authenticated by the Edge Function before this RPC.
 PERFORM 1 FROM remember.albums WHERE id=p_album AND owner_user_id=p_actor FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
 INSERT INTO remember.security_album_settings(album_id) VALUES(p_album)
 ON CONFLICT(album_id) DO NOTHING;
 PERFORM 1 FROM remember.security_album_settings WHERE album_id=p_album FOR UPDATE;
 CASE p_setting
  WHEN 'require_verified_email' THEN
   SELECT require_verified_email INTO v_before FROM remember.security_album_settings WHERE album_id=p_album;
   UPDATE remember.security_album_settings SET require_verified_email=p_enabled,updated_by=p_actor,updated_at=now() WHERE album_id=p_album;
  WHEN 'require_photo_approval' THEN
   SELECT require_photo_approval INTO v_before FROM remember.security_album_settings WHERE album_id=p_album;
   UPDATE remember.security_album_settings SET require_photo_approval=p_enabled,updated_by=p_actor,updated_at=now() WHERE album_id=p_album;
  WHEN 'allow_reports' THEN
   SELECT allow_reports INTO v_before FROM remember.security_album_settings WHERE album_id=p_album;
   UPDATE remember.security_album_settings SET allow_reports=p_enabled,updated_by=p_actor,updated_at=now() WHERE album_id=p_album;
  WHEN 'notify_reports' THEN
   SELECT notify_reports INTO v_before FROM remember.security_album_settings WHERE album_id=p_album;
   UPDATE remember.security_album_settings SET notify_reports=p_enabled,updated_by=p_actor,updated_at=now() WHERE album_id=p_album;
  WHEN 'pause_new_slideshow_photos' THEN
   SELECT pause_new_slideshow_photos INTO v_before FROM remember.security_album_settings WHERE album_id=p_album;
   UPDATE remember.security_album_settings SET pause_new_slideshow_photos=p_enabled,updated_by=p_actor,updated_at=now() WHERE album_id=p_album;
 END CASE;
 INSERT INTO remember.security_settings_audit(actor_user_id,album_id,setting_scope,setting_key,previous_value,next_value)
 VALUES(p_actor,p_album,'album',p_setting,to_jsonb(v_before),to_jsonb(p_enabled));
 v_result:=jsonb_build_object('ok',true,'albumId',p_album,'setting',p_setting,'enabled',p_enabled);
 INSERT INTO remember.security_request_ledger(request_id,actor_user_id,request_payload,result)
 VALUES(p_request_id,p_actor,v_payload,v_result);
 RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.remember_security_webmaster_feature_write(p_actor uuid, p_feature text, p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_previous text; v_exists boolean;
BEGIN
 IF p_actor IS NULL OR NOT EXISTS(SELECT 1 FROM remember.webmasters WHERE user_id=p_actor)
 THEN RAISE EXCEPTION 'webmaster_required' USING ERRCODE='42501'; END IF;
 IF p_feature NOT IN ('verified_guest_email','photo_approval','guest_reports','report_notifications','slideshow_pause','quota_notifications')
 THEN RAISE EXCEPTION 'invalid_feature' USING ERRCODE='22023'; END IF;
 IF p_mode IS DISTINCT FROM 'OFF'
 THEN RAISE EXCEPTION 'feature_not_ready' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(176315,918);
 SELECT mode INTO v_previous FROM remember.security_feature_flags WHERE feature_key=p_feature;
 v_previous:=coalesce(v_previous,'OFF');
 IF v_previous<>'OFF' THEN
   INSERT INTO remember.security_feature_flags(feature_key,mode,updated_by) VALUES(p_feature,'OFF',p_actor)
   ON CONFLICT(feature_key) DO UPDATE SET mode='OFF',updated_at=now(),updated_by=p_actor;
   INSERT INTO remember.security_feature_mode_audit(actor_id,feature_key,previous_mode,new_mode)
   VALUES(p_actor,p_feature,v_previous,'OFF');
 END IF;
 RETURN jsonb_build_object('feature',p_feature,'mode','OFF','changed',v_previous<>'OFF');
END $function$

CREATE OR REPLACE FUNCTION public.remember_test_stale_upload_fixture_cleanup(p_photo uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM remember.stale_upload_simulation_fixtures WHERE photo_id=p_photo) THEN RETURN jsonb_build_object('removed',false,'reason','not_fixture'); END IF;
 DELETE FROM remember.album_photos WHERE id=p_photo;
 RETURN jsonb_build_object('removed',true);
END $function$

