CREATE OR REPLACE FUNCTION public.remember_test_stale_upload_recovery_claim(p_photo uuid, p_expected_state text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v remember.album_photos%ROWTYPE; v_token uuid:=gen_random_uuid(); v_claim remember.stale_upload_recovery_claims%ROWTYPE;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_photo IS NULL OR p_expected_state NOT IN ('reserved','uploading') THEN RETURN jsonb_build_object('claimed',false,'reason','invalid'); END IF;
 SELECT * INTO v FROM remember.album_photos WHERE id=p_photo FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('claimed',false,'reason','missing'); END IF;
 IF v.state IS DISTINCT FROM p_expected_state OR v.reservation_expires_at IS NULL OR v.reservation_expires_at >= now()-interval '1 hour'
 THEN RETURN jsonb_build_object('claimed',false,'reason','not_stale'); END IF;
 INSERT INTO remember.stale_upload_recovery_claims(photo_id,claim_token,claimed_at,expires_at)
 VALUES(v.id,v_token,now(),now()+interval '5 minutes')
 ON CONFLICT(photo_id) DO UPDATE
 SET claim_token=excluded.claim_token,claimed_at=excluded.claimed_at,expires_at=excluded.expires_at
 WHERE remember.stale_upload_recovery_claims.expires_at<now()
 RETURNING * INTO v_claim;
 IF NOT FOUND THEN RETURN jsonb_build_object('claimed',false,'reason','already_claimed'); END IF;
 RETURN jsonb_build_object('claimed',true,'photoId',v.id,'claimToken',v_claim.claim_token,
 'state',v.state,'objectKey',v.object_key,'digestHex',CASE WHEN v.content_sha256 IS NOT NULL THEN encode(v.content_sha256,'hex') ELSE NULL END);
END $function$

CREATE OR REPLACE FUNCTION public.remember_test_stale_upload_recovery_finalize(p_photo uuid, p_claim_token uuid, p_digest_hex text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v remember.album_photos%ROWTYPE; c remember.stale_upload_recovery_claims%ROWTYPE; approval boolean;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_photo IS NULL OR p_claim_token IS NULL OR p_digest_hex IS NULL OR p_digest_hex !~ '^[a-f0-9]{64}$'
 THEN RETURN jsonb_build_object('completed',false,'reason','invalid'); END IF;
 SELECT * INTO v FROM remember.album_photos WHERE id=p_photo FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('completed',false,'reason','missing'); END IF;
 SELECT * INTO c FROM remember.stale_upload_recovery_claims WHERE photo_id=p_photo FOR UPDATE;
 IF NOT FOUND OR c.claim_token IS DISTINCT FROM p_claim_token OR c.expires_at<=now()
 THEN RETURN jsonb_build_object('completed',false,'reason','claim_invalid'); END IF;
 IF v.state<>'uploading' OR v.reservation_expires_at>=now()-interval '1 hour'
 OR v.content_sha256 IS NULL OR encode(v.content_sha256,'hex')<>p_digest_hex
 THEN RETURN jsonb_build_object('completed',false,'reason','state_or_digest_changed'); END IF;
 approval:=public.remember_security_effective_feature_read(v.album_id,'photo_approval');
 IF approval THEN
  INSERT INTO remember.photo_approval_queue(photo_id,album_id)
  VALUES(v.id,v.album_id) ON CONFLICT(photo_id) DO NOTHING;
 END IF;
 UPDATE remember.album_photos SET state='ready' WHERE id=v.id;
 DELETE FROM remember.stale_upload_recovery_claims WHERE photo_id=v.id AND claim_token=p_claim_token;
 RETURN jsonb_build_object('completed',true,'awaitingApproval',approval);
END $function$

